-- More safety legislation for the knowledge base (titles checked against the Open Law Book, see kb/gov/wikisource.ts DEFAULT_TITLES):
-- an installation whose staff chose titles gets the new ones added to its choice (up to the limit of 150); an installation on the
-- default list gets them by itself. The import is switched on in a running installation (asked for by the unit); who sees the answers stays as chosen.
UPDATE gov_sources SET selection = (
    SELECT array_agg(t ORDER BY ord) FROM (
      SELECT t, min(ord) AS ord FROM (
        SELECT t, ord FROM unnest(selection) WITH ORDINALITY AS a(t, ord)
        UNION ALL
        SELECT t, 1000 + ord FROM unnest(ARRAY[
          'חוק החמרים המסוכנים', 'חוק למניעת מפגעי אסבסט ואבק מזיק', 'חוק הקרינה הבלתי מייננת', 'חוק עבודת נשים', 'חוק עבודת הנוער', 'חוק הרשות הארצית לכבאות והצלה',
          'תקנות ארגון הפיקוח על העבודה (ניטור סביבתי וניטור ביולוגי של גורמים מזיקים)', 'תקנות ארגון הפיקוח על העבודה (פעולה מונעת)',
          'תקנות הבטיחות בעבודה (הגנה על עיניים)', 'תקנות הבטיחות בעבודה (רצועת עליה)', 'תקנות הבטיחות בעבודה (התקנת דלת בתא מעלית)',
          'תקנות הבטיחות בעבודה (מכירה והשכרה של מכונות, מיתקנים וציוד)', 'תקנות הבטיחות בעבודה (כלים לשיקוע פינים בפעולה ישירה)',
          'תקנות הבטיחות בעבודה (בדיקה בלחץ הידרוסטטי של מיתקן לחץ)', 'תקנות הבטיחות בעבודה (התקני בטיחות במיתקן לחץ)', 'תקנות הבטיחות בעבודה (התקני בטיחות בדוד קיטור)',
          'תקנות הבטיחות בעבודה (מועדי בדיקות לדודי קיטור מיוחדים)', 'תקנות הבטיחות בעבודה (מפעיל דוד קיטור ודוד הסקה)',
          'תקנות הבטיחות בעבודה (בטיחות וגיהות תעסוקתית בעבודה עם גורמים מסוכנים במעבדות רפואיות, כימיות וביולוגיות)',
          'תקנות הבטיחות בעבודה (איסור עבודה בחמרים מסרטנים מסוימים)', 'תקנות הבטיחות בעבודה (גיהות תעסוקתית ובטיחות העוסקים בקרינת לייזר)',
          'תקנות הבטיחות בעבודה (גיהות תעסוקתית ובריאות העוסקים בקרינה מיננת)', 'תקנות הבטיחות בעבודה (גיהות תעסוקתית ובריאות העובדים באיזוציאנאטים)',
          'תקנות הבטיחות בעבודה (גיהות תעסוקתית ובריאות העובדים בבנזן)', 'תקנות הבטיחות בעבודה (גיהות תעסוקתית ובריאות העובדים בויניל-כלוריד)',
          'תקנות הבטיחות בעבודה (גיהות תעסוקתית ובריאות העובדים בזרניך (ארסן))', 'תקנות הבטיחות בעבודה (גיהות תעסוקתית ובריאות העובדים בכספית)',
          'תקנות הבטיחות בעבודה (גיהות תעסוקתית ובריאות העובדים בעופרת)', 'תקנות הבטיחות בעבודה (גיהות תעסוקתית ובריאות העובדים במתכות מסויימות)',
          'תקנות הבטיחות בעבודה (גיהות תעסוקתית ובריאות העובדים בממיסים פחמיימניים ארומטיים מסויימים)',
          'תקנות הבטיחות בעבודה (גיהות תעסוקתית ובריאות העובדים בממיסים פחמיימניים הלוגניים מסויימים)',
          'תקנות הבטיחות בעבודה (גיהות תעסוקתית ובריאות העובדים בחומרי הדברה שהם זרחנים אורגניים וקרבמטים)', 'תקנות הבטיחות בעבודה (עובדים בחמרי הדברה)',
          'תקנות החומרים המסוכנים (סיווג ופטור)', 'תקנות החומרים המסוכנים (סילוק פסולת רדיואקטיבית)', 'תקנות החומרים המסוכנים (יבוא ויצוא פסולת חומרים מסוכנים)',
          'תקנות למניעת מפגעי אסבסט ואבק מזיק (בקשה לרישיון עוסק באסבסט ותנאים נוספים)',
          'תקנות למניעת מפגעי אסבסט ואבק מזיק (פטור מרישיון ומהיתר לעבודת אסבסט ומניעת ניגוד עניינים)', 'תקנות הקרינה הבלתי מייננת',
          'תקנות עבודת נשים (עבודות אסורות, עבודות מוגבלות ועבודות מסוכנות)', 'תקנות עבודת נשים (עבודות בקרינה מייננת)',
          'תקנות עבודת הנוער (עבודות אסורות ועבודות מוגבלות)', 'תקנות הרשות הארצית לכבאות והצלה (כללי התנהגות ובטיחות אש בקיום מדורות)'
        ]) WITH ORDINALITY AS b(t, ord)
      ) u GROUP BY t ORDER BY min(ord) LIMIT 150
    ) x)
 WHERE key = 'wikisource' AND cardinality(selection) > 0;
UPDATE gov_sources SET enabled = true, last_run_at = NULL, updated_at = now() WHERE key = 'wikisource' AND EXISTS (SELECT 1 FROM users);   -- a running installation; a new one stays off until switched on. The next hourly check imports at once
